import assert from 'node:assert/strict';
import { createShop } from './src/inventory-reservations/index.mjs';
import { createClient } from './src/retry-idempotency/client.mjs';
import { Ledger } from './src/atomic-ledger/ledger.mjs';

// Inventory replay normalization, snapshots, tenant scope, and rollback.
const initial = { t: { a: 10, b: 2 }, u: { a: 4 } };
const shop = createShop(initial);
initial.t.a = 0;
const input = { tenant: 't', requestId: 'same', items: [{ sku: 'b', quantity: 1 }, { sku: 'a', quantity: 1 }, { sku: 'a', quantity: 2 }] };
const receipt = shop.reserve(input);
assert.deepEqual(receipt.items, [{ sku: 'a', quantity: 3 }, { sku: 'b', quantity: 1 }]);
receipt.items[0].quantity = 100;
input.items[0].quantity = 2;
assert.deepEqual(shop.reserve({ tenant: 't', requestId: 'same', items: [{ sku: 'a', quantity: 3 }, { sku: 'b', quantity: 1 }] }).items,
  [{ sku: 'a', quantity: 3 }, { sku: 'b', quantity: 1 }]);
assert.equal(shop.stock('t', 'a'), 7);
shop.reserve({ tenant: 'u', requestId: 'same', items: [{ sku: 'a', quantity: 1 }] });
assert.throws(() => shop.reserve({ tenant: 't', requestId: 'bad', items: [{ sku: 'a', quantity: 1 }, { sku: 'missing', quantity: 1 }] }));
assert.equal(shop.stock('t', 'a'), 7);
shop.reserve({ tenant: 't', requestId: 'bad', items: [{ sku: 'a', quantity: 1 }] });
assert.throws(() => shop.reserve({ tenant: 't', requestId: 'same', items: [{ sku: 'a', quantity: 4 }] }), /Conflicting request/);

// Retry key reuse, caller key preservation, retry policy and millisecond conversion.
let keyNum = 0, attempts = 0;
const seen = [];
const delays = [];
const request = createClient({
  keyFactory: () => `key-${++keyNum}`,
  sleep: async ms => delays.push(ms),
  transport: async ({ headers }) => { seen.push({ ...headers }); return { status: ++attempts < 2 ? 429 : 200, headers: { 'Retry-After': '1.5' } }; },
});
await request({ method: 'POST', url: '/', headers: { Keep: 'yes' } });
assert.equal(seen[0]['idempotency-key'], 'key-1');
assert.equal(seen[1]['idempotency-key'], 'key-1');
assert.equal(seen[1].Keep, 'yes');
assert.deepEqual(delays, [1500]);
await request({ method: 'POST', url: '/', headers: { 'Idempotency-Key': 'provided' } });
assert.equal(seen.at(-1)['Idempotency-Key'], 'provided');
assert.equal(keyNum, 1);

// Atomic rollback, in-batch dedupe, and conflict handling.
const ledger = new Ledger({ a: 100, b: 0 });
assert.throws(() => ledger.applyBatch([{ id: 'x', from: 'a', to: 'b', amount: 40 }, { id: 'y', from: 'a', to: 'z', amount: 1 }]));
assert.deepEqual(ledger.snapshot(), { a: 100, b: 0 });
assert.deepEqual(ledger.applyBatch([
  { id: 'x', from: 'a', to: 'b', amount: 40 },
  { id: 'x', from: 'a', to: 'b', amount: 40 },
]), { a: 60, b: 40 });
assert.deepEqual(ledger.applyBatch([{ id: 'x', from: 'a', to: 'b', amount: 40 }]), { a: 60, b: 40 });
assert.throws(() => ledger.applyBatch([{ id: 'x', from: 'a', to: 'b', amount: 39 }]));
assert.deepEqual(ledger.snapshot(), { a: 60, b: 40 });
console.log('additional contract checks passed');
EOF

