export function delayFor(response, attempt, baseMs) {
  const headerName = Object.keys(response.headers ?? {}).find(name => name.toLowerCase() === 'retry-after');
  const retryAfter = headerName === undefined ? undefined : response.headers[headerName];
  if (retryAfter !== undefined && retryAfter !== null && String(retryAfter).trim() !== '') {
    const seconds = Number(retryAfter);
    if (Number.isFinite(seconds)) return seconds * 1000;
  }
  return baseMs * 2 ** (attempt - 1);
}
export function shouldRetry(response) {
